const nav=document.querySelector('#nav'),result=document.querySelector('#result'),title=document.querySelector('#title'),q=document.querySelector('#query'),count=document.querySelector('#count'),tools=document.querySelector('#chapter-tools');
let selected=0, completed={};const key='remote-sensing-progress-v1';try{completed=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{completed={}}
function saveProgress(){try{localStorage.setItem(key,JSON.stringify(completed))}catch{}}
function initBlackbody(){const temp=document.querySelector('#temp');if(!temp)return;function update(){let t=Number(temp.value);document.querySelector('#tempValue').textContent=t+' K';document.querySelector('#exitance').textContent=(5.67e-8*t**4).toExponential(3)+' W/m²';document.querySelector('#peak').textContent=(2898/t).toFixed(2)+' μm';document.querySelector('#blackbodyNote').textContent='温度上升时，出射度按四次方增长，波长峰值向短波移动。'}temp.addEventListener('input',update);update()}
function initMatrix(){const ids=['m11','m12','m21','m22'],els=ids.map(id=>document.getElementById(id));if(els.some(x=>!x))return;function update(){let vals=els.map(e=>e.value.trim()===''?NaN:Number(e.value));let out=document.getElementById('matrixResult');if(vals.some(v=>!Number.isInteger(v)||v<0)){out.textContent='请输入非负整数。';return}let [a,b,c,d]=vals,pct=(x,y)=>y?(100*x/y).toFixed(1)+'%':'无法计算（分母为零）';out.textContent='总体精度：'+pct(a+d,a+b+c+d)+'；植被生产者精度：'+pct(a,a+c)+'；植被用户精度：'+pct(a,a+b)}els.forEach(e=>e.addEventListener('input',update));update()}
function initBilinear(){const ids=['b00','b10','b01','b11','bu','bv'],e=ids.map(id=>document.getElementById(id));if(e.some(x=>!x))return;function update(){const a=e.slice(0,4).map(x=>x.value.trim()===''?NaN:Number(x.value)),u=Number(e[4].value),v=Number(e[5].value);document.getElementById('buval').textContent=u.toFixed(2);document.getElementById('bvval').textContent=v.toFixed(2);const out=document.getElementById('bilinearResult');if(a.some(x=>!Number.isFinite(x))){out.textContent='请输入四个有效数值。';return}let w=[(1-u)*(1-v),u*(1-v),(1-u)*v,u*v],bilinear=a.reduce((sum,x,i)=>sum+x*w[i],0),nearest=a[(v>=0.5?2:0)+(u>=0.5?1:0)];out.textContent='双线性结果：'+bilinear.toFixed(2)+'；最近邻结果：'+nearest.toFixed(2)+'。四角权重：'+w.map(x=>x.toFixed(3)).join('、')}e.forEach(x=>x.addEventListener('input',update));update()}
function initStretch(){const input=document.getElementById('stretch');if(!input)return;function update(){const x=Number(input.value),out=(x-84)*255/69;document.getElementById('stretchValue').textContent=x;document.getElementById('stretchResult').textContent='输出 = ('+x+' − 84) × 255 / 69 ≈ '+out.toFixed(2)}input.addEventListener('input',update);update()}
let mathChain=Promise.resolve();function typesetContent(){if(!window.MathJax||!MathJax.typesetPromise)return;mathChain=mathChain.then(()=>{if(MathJax.typesetClear)MathJax.typesetClear([result]);return MathJax.typesetPromise([result])}).catch(e=>console.warn('公式排版失败，保留浏览器默认显示',e))}
function render(){let query=q.value.trim().toLowerCase();nav.innerHTML='';SECTIONS.forEach((s,i)=>{let b=document.createElement('button');b.textContent=(completed[i]?'✓  ':'')+s.title.replace('《遥感概论》课程知识点汇总','复习总纲');b.className=i===selected&&!query?'active':'';b.onclick=()=>{selected=i;q.value='';render();window.scrollTo({top:0,behavior:'smooth'})};nav.append(b)});tools.innerHTML='';if(query){let matches=SECTIONS.filter(s=>(s.title+' '+s.html.replace(/<[^>]+>/g,' ')).toLowerCase().includes(query));title.textContent='搜索结果';count.textContent=`${matches.length} 个相关章节`;result.innerHTML=matches.length?matches.map(s=>`<div class="search-result"><h2>${s.title}</h2>${s.html}</div>`).join(''):'没有找到相关内容，试试其他关键词。'}else{title.textContent=SECTIONS[selected].title;const done=Object.keys(completed).filter(k=>completed[k]&&Number(k)>=1&&Number(k)<=9).length;count.textContent=`已复习 ${done}/9 章`;result.innerHTML=SECTIONS[selected].html;let headings=[...result.querySelectorAll('h2')];if(headings.length){let details=document.createElement('details');details.className='toc';let summary=document.createElement('summary');summary.textContent='本页目录 · '+headings.length+' 个小节';details.append(summary);let list=document.createElement('div');list.className='toc-links';headings.forEach((h,i)=>{h.id='topic-'+i;let a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent;list.append(a)});details.append(list);tools.append(details)}if(selected>=1&&selected<=9){let label=document.createElement('label');label.className='progress';let check=document.createElement('input');check.type='checkbox';check.checked=!!completed[selected];check.addEventListener('change',()=>{completed[selected]=check.checked;saveProgress();render()});label.append(check,document.createTextNode(' 标记本章已复习'));tools.append(label)}let note=document.createElement('small');note.className='storage-note';note.textContent='复习标记仅保存在当前浏览器';tools.append(note)}initBlackbody();initMatrix();initBilinear();initStretch();typesetContent()}
q.addEventListener('input',render);render();if(window.jQuery&&jQuery.fn.fancybox){jQuery(document).on('click','[data-fancybox]',function(e){e.preventDefault();jQuery.fancybox.open([{src:this.href,opts:{caption:this.dataset.caption}}])})}
